import { setServers } from 'node:dns';
import mongoose from 'mongoose';

/** Plain-language reasons for the usual MongoDB connection failures. */
export function describeConnectionError(error: unknown): string {
  const message = error instanceof Error ? error.message : String(error);
  if (/bad auth|authentication failed/i.test(message)) {
    return (
      'MongoDB rejected the username or password in the connection string. Check them in Atlas under ' +
      'Security → Database Access. Passwords with @ : / ? # need encoding, so an autogenerated one is easiest.'
    );
  }
  if (
    /Invalid connection string|must be (url|percent)[- ]encoded|unescaped characters/i.test(message)
  ) {
    return (
      'That connection string isn’t valid. A password with characters like @ : / ? # breaks it: ' +
      'in Atlas, edit the database user, click Autogenerate Secure Password, and copy the string again.'
    );
  }
  if (/ENOTFOUND|querySrv|ESERVFAIL|EREFUSED/i.test(message)) {
    return (
      'The MongoDB address in the connection string couldn’t be found. Copy the string from Atlas again ' +
      '(Clusters → Connect → Drivers), and check your internet connection.'
    );
  }
  if (/ECONNREFUSED/i.test(message)) {
    return 'Nothing is listening at that MongoDB address. Is MongoDB running?';
  }
  if (/Server selection timed out|timed out|ETIMEDOUT/i.test(message)) {
    return 'MongoDB didn’t answer. With MongoDB Atlas, add your current IP address under Security → Network Access.';
  }
  return message;
}

export type TidiedConnectionString =
  { ok: true; uri: string; encoded: boolean } | { ok: false; problem: string };

/** Percent-encodes a username or password, leaving one that is already encoded alone. */
function encodeCredential(part: string): string {
  try {
    if (encodeURIComponent(decodeURIComponent(part)) === part) return part;
  } catch {
    // A lone % (like "50%off") isn't an escape: encode it.
  }
  return encodeURIComponent(part);
}

/**
 * Cleans up a connection string pasted by hand: stray quotes and spaces, and passwords with
 * characters like @ : / ? # % that have to be percent-encoded. Spots the usual mistakes.
 */
export function tidyConnectionString(raw: string): TidiedConnectionString {
  const uri = raw
    .trim()
    .replace(/^MONGODB_URI\s*=\s*/i, '')
    .replace(/^(["'])(.*)\1$/s, '$2')
    .trim();
  if (!/^mongodb(\+srv)?:\/\//i.test(uri)) {
    return {
      ok: false,
      problem:
        'That doesn’t look like a connection string. It starts with mongodb+srv:// or mongodb://',
    };
  }
  if ((uri.match(/mongodb(\+srv)?:\/\//gi) ?? []).length > 1) {
    return {
      ok: false,
      problem: 'That looks like two connection strings pasted together. Paste just one.',
    };
  }
  if (/<db_(password|username)>|<(password|username)>/i.test(uri)) {
    return {
      ok: false,
      problem:
        'Replace <db_username> and <db_password> (including the < and >) with your database user’s ' +
        'name and password first.',
    };
  }

  const start = uri.indexOf('://') + 3;
  const at = uri.lastIndexOf('@');
  const host = uri.slice(at === -1 ? start : at + 1).split(/[/?]/)[0] ?? '';
  if (/\babcd123\b/i.test(host)) {
    return {
      ok: false,
      problem:
        'That’s the example from the instructions, not your cluster. Copy your own string from ' +
        'Atlas: Clusters → Connect → Drivers.',
    };
  }
  if (at === -1) return { ok: true, uri, encoded: false };

  const credentials = uri.slice(start, at);
  const colon = credentials.indexOf(':');
  const user = colon === -1 ? credentials : credentials.slice(0, colon);
  const password = colon === -1 ? null : credentials.slice(colon + 1);
  if (password !== null && /^<.*>$/.test(password)) {
    return {
      ok: false,
      problem: 'Remove the < and > around your password. Only the password itself goes there.',
    };
  }
  if (password === '') {
    return {
      ok: false,
      problem: 'The password is missing: it goes between the : and the @ after your username.',
    };
  }

  const tidyCredentials =
    encodeCredential(user) + (password === null ? '' : `:${encodeCredential(password)}`);
  return {
    ok: true,
    uri: uri.slice(0, start) + tidyCredentials + uri.slice(at),
    encoded: tidyCredentials !== credentials,
  };
}

/**
 * Atlas addresses (mongodb+srv://) need a DNS SRV lookup, which some home routers and ISPs
 * don't answer. If that lookup fails, try once more through public DNS servers.
 */
export async function connectWithDnsFallback(
  uri: string,
  dbName: string,
  timeoutMs = 10_000,
): Promise<void> {
  const options = { dbName, serverSelectionTimeoutMS: timeoutMs, appName: 'guff-api' };
  try {
    await mongoose.connect(uri, options);
  } catch (error) {
    const srvProblem =
      uri.startsWith('mongodb+srv://') &&
      /querySrv|ENOTFOUND|ESERVFAIL|EREFUSED|ECONNREFUSED/i.test(String(error));
    if (!srvProblem) throw error;
    await mongoose.disconnect().catch(() => {});
    setServers(['1.1.1.1', '8.8.8.8']);
    await mongoose.connect(uri, options);
  }
}
